<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import ContentExplorer from '@/components/ContentExplorer.vue'
import DestinationPicker from '@/components/trips/DestinationPicker.vue'
import AppSheet from '@/components/shared/AppSheet.vue'
import {allRecords} from '@/services/planner.service'
import {discoveryHandoff,discoverySelection} from '@/composables/discoverySession'
import type {Trip} from '@/types'
import type {Place} from '@/types/discovery'
import type {SuggestedVisit} from '@/composables/discovery'
import {useEditingViewport} from '@/composables/useEditingViewport'
useEditingViewport()
const router=useRouter(),picker=ref<InstanceType<typeof DestinationPicker>>(),choose=ref(false),trips=ref<Trip[]>([]),loading=ref(false),error=ref(''),opening=ref(false)
async function loadTrips(){loading.value=true;error.value='';try{trips.value=await allRecords<Trip>('trips')}catch{error.value='Your trips couldn’t load. Retry to choose a folder.'}finally{loading.value=false}}
function add(place:Place,date:string){discoveryHandoff.value={place,date};choose.value=true;void loadTrips()}
function plan(visits:SuggestedVisit[]){discoveryHandoff.value={visits,date:''};choose.value=true;void loadTrips()}
async function go(path:string){if(opening.value)return;opening.value=true;try{await router.push(path)}finally{opening.value=false}}
onMounted(()=>{void loadTrips()})
</script>
<template><main class="field-notes exploration"><section class="explore-hero"><div class="hero-copy"><p class="eyebrow">YOUR NEXT LITTLE ADVENTURE</p><h1>Somewhere new<br/><em>is calling.</em></h1><p>Find a place that speaks to you, then tuck it into a travel folder for the day you go.</p><button class="explore-cta" @click="picker?.show()">Find a place <span>↗</span></button><div class="hero-caption"><span class="compass">N</span><span>TAKE THE SCENIC ROUTE</span></div></div><div class="hero-art" aria-hidden="true"><span class="sun-disc"></span><span class="art-label">FIELD NOTES · NO. 01</span><span class="mountain mountain-back"></span><span class="mountain mountain-front"></span><span class="art-coast"></span><span class="art-water">P H I L I P P I N E S</span></div></section><DestinationPicker ref="picker" :destination="discoverySelection?.name||''" :location="{destination_latitude:discoverySelection?.latitude,destination_longitude:discoverySelection?.longitude,destination_source:discoverySelection?'map':null}" @remember="discoverySelection=$event" @change="(name,pin)=>discoverySelection=pin.destination_latitude!=null&&pin.destination_longitude!=null?{name,latitude:pin.destination_latitude,longitude:pin.destination_longitude}:null" @recommend="add" @plan="plan" /><section class="explore-tools"><div><p class="eyebrow">MAKE A LITTLE PLAN</p><h2>From daydream to itinerary.</h2><p>Choose a destination, save the places that catch your eye, and add them to a trip when you’re ready.</p></div><button class="outline-cta" @click="go('/trips')">See my trips <span>↗</span></button></section><details class="saved-places"><summary><span><small>YOUR PERSONAL ATLAS</small><strong>Places woven into your memories</strong></span><span class="summary-arrow">＋</span></summary><div class="saved-map-content"><ContentExplorer mode="map" /></div></details><AppSheet :model-value="choose" title="Choose a trip folder" @update:model-value="choose=$event"><p>Review the place and choose its date and times inside your trip.</p><p v-if="loading" role="status">Opening your folders…</p><p v-if="error" role="alert">{{error}} <button @click="loadTrips">Retry</button></p><div class="trip-choices"><button v-for="trip in trips" :key="trip.id" :disabled="opening" @click="go('/trips/'+trip.id+'?discover=1')">{{trip.title}}</button><button class="primary" :disabled="opening" @click="go('/trips/new?from=discovery')">New trip</button></div></AppSheet></main></template>
